create or replace function public.ils_professional_security_reviewer_is_authorized(p_user_id uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists (select 1 from public.ils_professional_security_reviewer_authorizations r where r.user_id=p_user_id and r.authorization_status='ACTIVE' and r.reviewer_role in ('SECURITY_REVIEWER','SECURITY_ADMIN') and r.identity_verified=true and r.security_training_verified=true and (r.valid_from is null or r.valid_from <= now()) and (r.valid_until is null or r.valid_until >= now())); $$; revoke all on function public.ils_professional_security_reviewer_is_authorized(uuid) from public,anon; grant execute on function public.ils_professional_security_reviewer_is_authorized(uuid) to service_role;